head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.ui_btn01_onclick = function(e) {
    ui_wframe.setSrc("progressbar_setInterval_WPFF-97_(WSQ-3572)_sub.xml");
};
scwin.ui_btn02_onclick = function(e) {
    ui_wframe.setSrc("progressbar_setInterval_WPFF-97_(WSQ-3572)_blank.xml");
};
scwin.checkLog = function() {
    return WebSquare.logger.getErrorLog() == '';
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('ui_btn01').click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('ui_btn02').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkLog()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
